#!/bin/sh
# Orchestrator git hook. Generated by Orchestrator; edits are overwritten.
#
# A session worktree points core.hooksPath (worktree scope only) at this
# directory. Every hook name is a copy of this script. prepare-commit-msg and
# commit-msg add Orchestrator's Co-authored-by trailer; every hook then hands
# off to the hook the repository itself would have run (a hook manager's
# core.hooksPath or .git/hooks), so the repository's own hooks keep working.

hook=$(basename "$0")
here=$(cd "$(dirname "$0")" 2>/dev/null && pwd -P)

# original_hook prints the hook the repository would run without Orchestrator:
# a hooksPath this worktree's config had before Orchestrator replaced it, else
# core.hooksPath from the repository, global or system config (read live, so a
# hooksPath a hook manager sets after the session started still runs), else the
# shared hooks directory.
original_hook() {
	dir=$(git config --worktree --type=path --get orchestrator.originalHooksPath 2>/dev/null)
	if [ -z "$dir" ]; then
		dir=$(git config --type=path --show-scope --get-all core.hooksPath 2>/dev/null |
			awk -F '\t' '$1 != "worktree" { v = $2 } END { print v }')
	fi
	if [ -z "$dir" ]; then
		dir=$(git rev-parse --git-common-dir 2>/dev/null) || return 0
		dir="$dir/hooks"
	fi
	resolved=$(cd "$dir" 2>/dev/null && pwd -P) || return 0
	[ "$resolved" = "$here" ] && return 0
	if [ -f "$resolved/$hook" ] && [ -x "$resolved/$hook" ]; then
		printf '%s\n' "$resolved/$hook"
	fi
}

# replaying reports whether git is replaying existing commits (a rebase or a
# cherry-pick). Those commits were written before, often by someone else, so
# they keep the message they had. A revert is a new commit and is credited.
# While a rebase is stopped (an edit stop, or an --exec step) every commit is
# skipped, including a new one the agent writes there: telling it apart from a
# replayed pick needs rebase-merge/done bookkeeping, not worth it for that case.
replaying() {
	for name in rebase-merge rebase-apply CHERRY_PICK_HEAD; do
		path=$(git rev-parse --git-path "$name" 2>/dev/null) || continue
		[ -e "$path" ] && return 0
	done
	return 1
}

# comment_awk runs awk program $1 on file $2 with two helpers: comment(line),
# whether a line is a comment, and scissors(line), whether it is the
# `git commit -v` scissors line. The comment string is matched literally. With
# core.commentChar=auto git picks a character the message does not start a
# line with, so any of git's candidates counts as a comment there; at worst
# that skips the trailer, never breaks the commit. Like git, the scissors line
# must be exactly the comment string, a space and the cut marker.
comment_awk() {
	cs=$(git config --get core.commentString 2>/dev/null) ||
		cs=$(git config --get core.commentChar 2>/dev/null) || cs='#'
	[ -n "$cs" ] || cs='#'
	# The comment string goes through the environment: awk -v would treat its
	# backslashes as escapes.
	ORCHESTRATOR_CS=$cs awk '
		function comment(line,   i) {
			if (cs != "auto") return index(line, cs) == 1
			for (i = 1; i <= length(auto); i++)
				if (substr(line, 1, 1) == substr(auto, i, 1)) return 1
			return 0
		}
		function scissors(line) {
			if (cs != "auto") return line == cs " " cut
			return comment(line) && substr(line, 2) == " " cut
		}
		BEGIN { cs = ENVIRON["ORCHESTRATOR_CS"]; auto = "#;@!$%^&|:"; cut = "------------------------ >8 ------------------------" }
	'"$1" "$2"
}

# strips_comments reports whether git drops comment lines from an edited
# message: commit.cleanup unset, default or strip. whitespace, scissors and
# verbatim keep them. A --cleanup option on the command line is not visible
# to the hook.
strips_comments() {
	case $(git config --get commit.cleanup 2>/dev/null) in
	whitespace | scissors | verbatim) return 1 ;;
	esac
	return 0
}

# normalize reads a message on stdin and tidies it as git's cleanup does.
normalize() {
	if strips_comments; then
		git stripspace --strip-comments 2>/dev/null
	else
		git stripspace 2>/dev/null
	fi
}

# has_message reports whether the message file holds anything besides
# whitespace and, when git strips them, comment lines. `git commit -v`
# appends a diff below a scissors line; it is not message.
has_message() {
	strip=1
	strips_comments || strip=0
	comment_awk '
		BEGIN { found = 0; strip = '"$strip"' }
		scissors($0) { exit }
		!(strip && comment($0)) && $0 ~ /[^ \t\r]/ { found = 1; exit }
		END { exit !found }
	' "$1"
}

# A commit whose message comes from a template (commit.template or -t) is
# snapshotted by prepare-commit-msg, before the editor opens. Git aborts the
# commit if the message is still that template ("you did not edit the
# message"); adding the trailer would change it and let the commit through, so
# commit-msg leaves an unedited template alone.
template_snapshot() {
	git rev-parse --git-path ORCHESTRATOR_TEMPLATE 2>/dev/null
}

# snapshot_template records message file $1 when $2, the commit source, is a
# template, and clears any snapshot an earlier, aborted commit left.
snapshot_template() {
	snap=$(template_snapshot) || return 0
	[ -n "$snap" ] || return 0
	rm -f "$snap"
	if [ "$2" = template ] && [ -n "$1" ] && [ -f "$1" ]; then
		# With -s git has already added the committer's sign-off; git compares
		# against the template without it, so the snapshot leaves that one
		# line out. Sign-offs written in the template itself stay: when the
		# configured commit.template ends with the committer's own sign-off,
		# the line is the template's. (A -t file is not visible to the hook.)
		ident=$(git var GIT_COMMITTER_IDENT 2>/dev/null | sed 's/ [0-9]* [-+][0-9]*$//')
		signoff="Signed-off-by: $ident"
		full=$(message_text "$1")
		# commit.cleanup=whitespace keeps the help git appends below the
		# template as comment lines; git compares against the template alone.
		if [ "$(git config --get commit.cleanup 2>/dev/null)" = whitespace ] &&
			[ "$(git config --type=bool --get commit.status 2>/dev/null)" != false ]; then
			full=$(printf '%s\n' "$full" | comment_awk '
				{ line[NR] = $0 }
				!comment($0) && $0 ~ /[^ \t\r]/ { last = NR }
				END { for (i = 1; i <= last; i++) print line[i] }
			' -)
		fi
		tpl=$(git config --path --get commit.template 2>/dev/null) &&
			[ -f "$tpl" ] && [ "$(normalize <"$tpl")" = "$full" ] && signoff=
		printf '%s\n' "$full" | ORCHESTRATOR_SIGNOFF=$signoff awk '
			{ line[NR] = $0 }
			!/^[[:space:]]*$/ { last = NR }
			END {
				if (last && ENVIRON["ORCHESTRATOR_SIGNOFF"] != "" && line[last] == ENVIRON["ORCHESTRATOR_SIGNOFF"]) {
					last--
					while (last && line[last] ~ /^[[:space:]]*$/) last--
				}
				for (i = 1; i <= last; i++) print line[i]
			}
		' >"$snap" || rm -f "$snap"
	fi
}

# message_text prints the message in file $1 the way git reads it: without
# the `commit -v` scissors line and the diff below it, and without comment
# lines when the cleanup mode strips them.
message_text() {
	comment_awk 'scissors($0) { exit } { print }' "$1" | normalize
}

# only_signoffs reports whether text $1 holds nothing but blank lines and
# Signed-off-by lines: git treats such a message as empty, and a template
# followed only by them as unedited.
only_signoffs() {
	printf '%s\n' "$1" | awk '!/^[[:space:]]*$/ && !/^Signed-off-by: / { found = 1 } END { exit found }'
}

# template_untouched reports whether message file $1 is still the template
# this commit started from, and consumes the snapshot.
template_untouched() {
	snap=$(template_snapshot) || return 1
	[ -n "$snap" ] && [ -f "$snap" ] || return 1
	# With commit.cleanup=verbatim git never treats a message as the template.
	if [ "$(git config --get commit.cleanup 2>/dev/null)" = verbatim ]; then
		rm -f "$snap"
		return 1
	fi
	text=$(message_text "$1")
	snapshot=$(cat "$snap")
	rm -f "$snap"
	# Git's own rule: the template, then nothing but whitespace and sign-offs.
	case "$text" in
	"$snapshot"*) rest=${text#"$snapshot"} ;;
	*) rest=$text ;;
	esac
	only_signoffs "$rest"
}

# insert_trailer adds trailer $2 to message file $1 with none of the person's
# trailer.* config: no separators, placement, or trailer.<token>.cmd that
# could rewrite or duplicate it. git runs outside any repository with the
# global and system config switched off; only the comment string carries over,
# so comment lines and a `commit -v` scissors line are still recognised.
# --no-divider: a "---" line in the body is not a patch divider here.
# With $3 = literal (a -m or -F message), nothing in the message is a comment:
# the comment character is one no message contains, so a "#" line is kept.
insert_trailer() {
	case "$1" in /*) file=$1 ;; *) file=$PWD/$1 ;; esac
	trailer=$2
	if [ "$3" = literal ]; then
		comment=$(printf '\001')
	else
		comment=$(git config --get core.commentString 2>/dev/null) ||
			comment=$(git config --get core.commentChar 2>/dev/null) || comment=
	fi
	(
		unset GIT_DIR GIT_WORK_TREE GIT_INDEX_FILE GIT_COMMON_DIR GIT_PREFIX \
			GIT_CONFIG GIT_CONFIG_PARAMETERS GIT_CONFIG_COUNT
		GIT_CONFIG_GLOBAL=/dev/null GIT_CONFIG_NOSYSTEM=1 GIT_CEILING_DIRECTORIES=$(dirname "$here")
		export GIT_CONFIG_GLOBAL GIT_CONFIG_NOSYSTEM GIT_CEILING_DIRECTORIES
		cd "$here" || exit 0
		set --
		if [ -n "$comment" ] && [ "$comment" != auto ]; then
			if [ "${#comment}" -eq 1 ]; then
				set -- -c "core.commentChar=$comment"
			else
				set -- -c "core.commentString=$comment"
			fi
		fi
		git "$@" interpret-trailers --in-place --no-divider --where end \
			--if-exists addIfDifferent --if-missing add --trailer "$trailer" "$file"
	) 2>/dev/null || true
}

# add_trailer adds the trailer to the message file in $1. $2 is the commit
# source git passes to prepare-commit-msg (empty for commit-msg).
add_trailer() {
	msg=$1
	[ -n "$msg" ] && [ -f "$msg" ] || return 0
	[ "$2" = merge ] && return 0
	# A merge commit (git merge, or a conflicted merge being concluded).
	merge_head=$(git rev-parse --git-path MERGE_HEAD 2>/dev/null)
	[ -n "$merge_head" ] && [ -f "$merge_head" ] && return 0
	replaying && return 0
	coauthor=$(git config --get orchestrator.coauthor 2>/dev/null)
	[ -n "$coauthor" ] || return 0
	# Already there (added by prepare-commit-msg, or kept by an amend): leave
	# the message exactly as it is.
	grep -Fqx "Co-authored-by: $coauthor" "$msg" && return 0
	# -m and -F messages are taken as written: nothing in them is a comment.
	# Otherwise, with nothing written yet the editor is about to open; commit-msg
	# adds the trailer after it closes, and an empty message still aborts.
	if [ "$2" = template ]; then
		# Left to commit-msg, after the editor, so an unedited template still aborts.
		return 0
	elif [ "$2" != message ]; then
		has_message "$msg" || return 0
		template_untouched "$msg" && return 0
		# Nothing but sign-offs: git aborts it as an empty message.
		only_signoffs "$(message_text "$msg")" && return 0
		insert_trailer "$msg" "Co-authored-by: $coauthor"
	elif ! only_signoffs "$(cat "$msg")"; then
		# git commit -s -m "" holds only a sign-off, which git aborts as empty.
		insert_trailer "$msg" "Co-authored-by: $coauthor" literal
	fi
}

original=$(original_hook)
case "$hook" in
prepare-commit-msg | commit-msg)
	if [ "$hook" = prepare-commit-msg ]; then
		snapshot_template "$1" "$2"
	fi
	if [ -n "$original" ]; then
		"$original" "$@" || exit $?
	fi
	add_trailer "$1" "$2"
	exit 0
	;;
esac
if [ -n "$original" ]; then
	exec "$original" "$@"
fi
exit 0
